from pathlib import Path
import base64,lzma,hashlib,subprocess,tempfile,ast,re,unicodedata,threading,types
root=Path(__file__).resolve().parents[1]
source=root/'EmbyFlowE2_KinoCheck_20261003_0301.py'
assert hashlib.sha256(source.read_bytes()).hexdigest()=='01ea0a92517036b0b93047b09442034a9288d3a951877860707d605ff99028ef'
with tempfile.TemporaryDirectory() as d:
    p=Path(d)/'plugin.py';p.write_bytes(source.read_bytes())
    subprocess.run(['patch','--batch','--forward',str(p)],input=lzma.decompress(base64.b64decode('')),check=True)
    data=p.read_bytes()
compile(data,'plugin.py','exec')
assert hashlib.sha256(data).hexdigest()=='eaaa904a3de7bb4c311a3037b5fde67323ab07748f2ac306181beec74d2f3df7'
