ns={'_trall_re':re,'_trall_unicode':unicodedata,'_trcache_log':lambda message:None}
for node in ast.parse(data).body:
    if isinstance(node,ast.FunctionDef) and node.name in ('_trall_words','_trall_queries','_trall_score'):
        exec(compile(ast.Module(body=[node],type_ignores=[]),'filter','exec'),ns)
