entry={'channel':'Biotider','title':'Den osynlige (2002) | Trailer','duration':120}
assert ns['_trall_score'](entry,meta) is not None
assert ns['_trall_score'](dict(entry,channel='KinoCheck'),meta)>ns['_trall_score'](entry,meta)
for title in ('Den osynlige Trailer','Den osynlige (2007) Trailer','Den osynlige (2002) Fan Made Trailer','Other (2002) Trailer'):
    assert ns['_trall_score'](dict(entry,title=title),meta) is None
assert len(ns['_trall_queries'](meta))==2
# Actual failure cache: immediate repeat, expiration, cancellation, success.
clock=[0];calls=[];status=[1]
class Process:
    def __init__(self):self.returncode=status[0]
    def communicate(self,*a,**kw):return b'',b'error'
def popen(command,*a,**kw):calls.append(command);return Process()
ns={'_trcache_threading':threading,'_trcache_time':types.SimpleNamespace(monotonic=lambda:clock[0]),'_trcache_log':lambda message:None,'_trpref_original_popen':popen}
text=data.decode();exec(text[text.index('# EMBYFLOW_TRAILER_FAILURE_CACHE_LOCAL1'):],ns)
f=ns['_trpref_original_popen']
f(['a']).communicate();f(['a']).communicate();assert len(calls)==1
